def compute(vars):
    effective_rate = vars["v1"]
    statutory_rate = vars["v2"]
    difference = effective_rate - statutory_rate

    return {
        "value": difference,
        "trace": {
            "effective_rate": effective_rate,
            "statutory_rate": statutory_rate,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
